let kiraSceneFrame=0,kiraSceneResize=null;
function initKiraDimension(){
 const host=$('.kira-world'),canvas=$('#kira-dimension-canvas');
 if(!host||!canvas||!window.THREE)return;
 if(kiraSceneFrame)cancelAnimationFrame(kiraSceneFrame);
 if(kiraSceneResize)window.removeEventListener('resize',kiraSceneResize);
 const THREE=window.THREE,scene=new THREE.Scene();
 scene.fog=new THREE.FogExp2(0x10152e,.035);
 const camera=new THREE.PerspectiveCamera(48,1,.1,100);camera.position.set(0,0,17);
 let renderer;try{renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'})}catch(err){canvas.hidden=true;return}
 renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.6));renderer.setClearColor(0x000000,0);
 const group=new THREE.Group();scene.add(group);
 const ambient=new THREE.AmbientLight(0xaaaaff,1.6);scene.add(ambient);
 const magenta=new THREE.PointLight(0xff39b8,28,30);magenta.position.set(-5,2,5);scene.add(magenta);
 const blue=new THREE.PointLight(0x657bff,24,30);blue.position.set(5,-3,3);scene.add(blue);
 const rings=[];
 [[5.5,0.045,0x9a76ff],[4.5,0.025,0xff4ab8],[6.4,0.018,0x65d9ff]].forEach((v,i)=>{const m=new THREE.Mesh(new THREE.TorusGeometry(v[0],v[1],8,180),new THREE.MeshBasicMaterial({color:v[2],transparent:true,opacity:i===1?.48:.28}));m.rotation.set(.8+i*.38,.2+i*.42,i*.65);m.position.set(.5,0,-1-i*.6);group.add(m);rings.push(m)});
 const dustCount=1300,positions=new Float32Array(dustCount*3),colors=new Float32Array(dustCount*3);
 const palette=[new THREE.Color(0xff58bd),new THREE.Color(0x8d83ff),new THREE.Color(0x69d9ff),new THREE.Color(0xf0eaff)];
 for(let i=0;i<dustCount;i++){const radius=2+Math.random()*10,angle=Math.random()*Math.PI*2,spread=(Math.random()-.5)*5;positions[i*3]=Math.cos(angle)*radius;positions[i*3+1]=Math.sin(angle)*radius*.58+spread*.4;positions[i*3+2]=(Math.random()-.5)*13;const c=palette[Math.floor(Math.random()*palette.length)];colors[i*3]=c.r;colors[i*3+1]=c.g;colors[i*3+2]=c.b}
 const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(positions,3));geo.setAttribute('color',new THREE.BufferAttribute(colors,3));
 const stars=new THREE.Points(geo,new THREE.PointsMaterial({size:.035,vertexColors:true,transparent:true,opacity:.85,depthWrite:false}));group.add(stars);
 const core=new THREE.Mesh(new THREE.SphereGeometry(2.15,48,48),new THREE.MeshBasicMaterial({color:0x8065e8,transparent:true,opacity:.055,wireframe:true}));core.position.set(.4,-.15,.1);group.add(core);
 const resize=()=>{if(!host.isConnected)return;const w=Math.max(1,host.clientWidth),h=Math.max(1,host.clientHeight);renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()};
 kiraSceneResize=resize;window.addEventListener('resize',resize,{passive:true});resize();
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;let t=0,targetX=0,targetY=0;
 const onPointerMove=e=>{if(reduced||e.pointerType==='touch')return;const rect=host.getBoundingClientRect();targetY=((e.clientX-rect.left)/Math.max(1,rect.width)-.5)*.12;targetX=((e.clientY-rect.top)/Math.max(1,rect.height)-.5)*-.08};
 const onPointerLeave=()=>{targetX=0;targetY=0};
 host.addEventListener('pointermove',onPointerMove,{passive:true});host.addEventListener('pointerleave',onPointerLeave,{passive:true});
 function animate(){if(!host.isConnected){host.removeEventListener('pointermove',onPointerMove);host.removeEventListener('pointerleave',onPointerLeave);renderer.dispose();return}kiraSceneFrame=requestAnimationFrame(animate);if(document.hidden)return;if(!reduced){t+=.0018;group.rotation.y+=(Math.sin(t)*.1+targetY-group.rotation.y)*.025;group.rotation.x+=(targetX-group.rotation.x)*.025;group.rotation.z=Math.sin(t*.65)*.035;stars.rotation.z+=.00012;rings.forEach((r,i)=>{r.rotation.z+=(i%2?.0008:-.00055);r.rotation.x+=.00015});magenta.intensity=24+Math.sin(t*3)*4;blue.intensity=22+Math.cos(t*2)*4}renderer.render(scene,camera)}
 animate();
}
async function startKiraWork(){const products=Array.isArray(data.settings.inventorySummary?.products)?data.settings.inventorySummary.products.filter(p=>{const n=Number(String(p.stock??'').replace(/,/g,''));return !String(p.stock??'').trim()||!Number.isFinite(n)||n>0}):[];const product=products[0]||null;const business=data.settings.business||'your business';const name=product?'Kira’s '+product.name+' spotlight':business+' community spark';const offer=product?'A friendly, nostalgia-led spotlight on '+product.name+(product.category?' ('+product.category+')':'')+(product.price?' at the listed price of '+product.price:'')+'. No invented discount or stock claim.':'A community-first introduction to '+business+', what makes it different, and a question that invites real customer stories. No invented offer or discount.';const c=makeCampaign({name,offer,audience:data.settings.audience||'Existing customers and people who would genuinely enjoy the business',goal:product?'Engagement':'Community growth',angle:product?'nostalgia':'community'});c.createdBy='Kira';c.strategy='Kira-led draft built from the saved business profile and available inventory. Owner approval required before publication.';const now=new Date().toISOString();let operation={id:'local-op-'+Date.now().toString(36),businessId:data.settings.activeBusinessId||'legacy-default',type:'campaign_preparation',title:'Prepare campaign: '+c.name,summary:'Create a focused, evidence-grounded campaign draft for '+business+'.',status:'queued',priority:'normal',source:{kind:'kira',label:'Kira next move'},createdAt:now,updatedAt:now,history:[{status:'queued',at:now,by:'kira'}]};data.operations=[operation,...(data.operations||[])];save();if(hasCloudSession()){try{const created=await apiRequest('/api/operations',{method:'POST',body:JSON.stringify({type:operation.type,title:operation.title,summary:operation.summary,priority:operation.priority,source:operation.source})});operation=created.operation;data.operations[0]=operation;const started=await apiRequest('/api/operations/'+operation.id,{method:'PATCH',body:JSON.stringify({status:'in_progress',by:'kira',note:'Kira started preparing the campaign draft.'})});operation=started.operation;data.operations[0]=operation;save()}catch(err){console.warn('Could not sync Kira operation:',err.message)}}let aiBuilt=false;if(hasCloudSession()){try{const generated=await apiRequest('/api/generate',{method:'POST',body:JSON.stringify({name:c.name,offer:c.offer,audience:c.audience,goal:c.goal,marketingGoal:data.settings.marketingGoal||c.goal,angle:c.angle,business:data.settings.business,businessDescription:data.settings.businessDescription||'',inventorySummary:aiInventoryContext(),brandVoice:data.settings.voice,platforms:(data.settings.platforms||'').split(',').map(x=>x.trim()).filter(Boolean),channelSetup:data.settings.channelSetup||{}})});const g=generated.campaign||{};if(Array.isArray(g.posts)&&g.posts.length===3){c.strategy=g.strategy||c.strategy;c.audienceInsight=g.audienceInsight||'';c.channelPlan=Array.isArray(g.channelPlan)?g.channelPlan:[];c.successMetrics=Array.isArray(g.successMetrics)?g.successMetrics:[];c.posts=c.posts.map((old,i)=>({...old,...g.posts[i],id:old.id,status:'pending',scheduledDate:'',metrics:old.metrics||{}}));aiBuilt=true}}catch(err){console.warn('Kira could not reach live AI; using a local draft:',err.message)}}data.campaigns.push(c);save();if(hasCloudSession()){try{await saveCloudCampaign(c)}catch(err){notify('Kira’s draft is saved here; cloud sync failed: '+err.message)}}operation={...operation,status:'awaiting_owner',updatedAt:new Date().toISOString(),result:'Campaign draft “'+c.name+'” is ready for owner review.',history:[...(operation.history||[]),{status:'awaiting_owner',at:new Date().toISOString(),by:'kira',note:'Draft saved to campaign review.'}]};if(hasCloudSession()&&!operation.id.startsWith('local-op-')){try{operation=(await apiRequest('/api/operations/'+operation.id,{method:'PATCH',body:JSON.stringify({status:'awaiting_owner',by:'kira',note:'Campaign draft saved to owner review.',result:operation.result})})).operation}catch(err){console.warn('Could not update Kira operation:',err.message)}}data.operations=[operation,...(data.operations||[]).filter(x=>x.id!==operation.id)];save();view='approvals';render();notify(aiBuilt?'Kira has prepared a campaign with the live AI service. It’s waiting for your OK.':'Kira has prepared a campaign draft. Connect live AI for richer generation. Nothing is published without your OK.')}
function dashboard(){const pending=data.campaigns.filter(c=>c.status==='pending').length;return '<section class="kira-world"><canvas id="kira-dimension-canvas" class="kira-dimension-canvas" aria-hidden="true"></canvas><div class="dimension-vignette" aria-hidden="true"></div><div class="cloud cloud-back"></div><div class="cloud cloud-mid"></div><div class="cloud cloud-front"></div><div class="kira-world-copy"><p class="eyebrow">YOUR MARKETING DIRECTOR</p><h1>I’m Kira.</h1><p class="kira-world-line">Your marketing, handled.</p><p class="kira-world-intro">'+esc(data.settings.business?'I’m here to move '+data.settings.business+' forward. ':'I’ll get the good stuff made and bring you in only when I need your call. ')+'You make the calls. I’ll keep us moving.</p><div class="kira-world-actions"><button class="btn btn-primary" data-view="approvals">Approvals'+(pending?' · '+pending:'')+'</button><button class="btn btn-world-secondary" data-action="kira-start-work">Let Kira work ✨</button></div><button class="kira-voice-button" data-action="kira-welcome" aria-label="Hear Kira’s introduction"><span class="sound-wave" aria-hidden="true">)))</span><span>Meet Kira</span></button></div><div class="kira-world-figure">'+kiraAvatar('large')+'<div class="kira-glow"></div><div class="kira-nameplate"><b>KIRA</b><small>YOUR MARKETING DIRECTOR</small></div></div><button class="world-menu-link" data-action="open-menu" aria-label="Open workspace menu">☰</button><nav class="dimension-portals" aria-label="Kira’s marketing world"><button class="dimension-portal" data-action="kira-start-work"><span class="portal-icon">✳</span><span><b>Kira’s next move</b><small>Build a campaign draft</small></span></button><button class="dimension-portal" data-view="approvals"><span class="portal-icon">✓</span><span><b>To review</b><small>'+pending+'</small></span></button><button class="dimension-portal" data-view="schedule"><span class="portal-icon">◷</span><span><b>Schedule</b><small>What goes out</small></span></button><button class="dimension-portal" data-view="results"><span class="portal-icon">↗</span><span><b>Saved work</b><small>Learn & improve</small></span></button><button class="dimension-portal" data-view="connections"><span class="portal-icon">◎</span><span><b>Channels</b><small>Connected tools</small></span></button></nav></section>'}


async function researchOpportunities(existingOperationId=null){
if(!hasCloudSession()){notify('Connect and sign in to the live workspace in Settings before running current web research.');return}
const business=String(data.settings.business||'').trim();if(!business){notify('Add the business name in Settings before researching.');return}
if(existingOperationId&&operationRuns.has(existingOperationId))return;
let op=null;
try{
if(existingOperationId){
op=(data.operations||[]).find(x=>x.id===existingOperationId);
if(!op||op.type!=='opportunity_assessment'||op.status!=='blocked'){notify('Only blocked research operations can be resumed here.');return}
operationRuns.add(existingOperationId);
const queued=await apiRequest('/api/operations/'+op.id,{method:'PATCH',body:JSON.stringify({status:'queued',by:'owner',note:'Owner requested a fresh research attempt using the current business settings.'})});
op=queued.operation;
}else{
const created=await apiRequest('/api/operations',{method:'POST',body:JSON.stringify({type:'opportunity_assessment',title:'Research opportunities for '+business,summary:'Search current public sources for relevant customer, category, seasonal and competitor signals.',priority:'high',source:{kind:'kira',label:'Live web research'}})});
op=created.operation;operationRuns.add(op.id);
}
const started=await apiRequest('/api/operations/'+op.id,{method:'PATCH',body:JSON.stringify({status:'in_progress',by:'kira',note:existingOperationId?'Kira resumed live research using the current business settings.':'Kira started a live, source-backed research run.'})});
op=started.operation;data.operations=[op,...(data.operations||[]).filter(x=>x.id!==op.id)];save();if(view==='operations')render();
const result=await apiRequest('/api/research',{method:'POST',body:JSON.stringify({business,businessDescription:data.settings.businessDescription||'',location:data.settings.businessLocation||'',audience:data.settings.audience||'',platforms:(data.settings.platforms||'').split(',').map(x=>x.trim()).filter(Boolean),inventorySummary:aiInventoryContext()})});
const evidence=(result.sources||[]).slice(0,10).map(x=>({label:x.label,url:x.url,observedAt:result.researchedAt,note:'Source returned by live web research.'}));
const finished=await apiRequest('/api/operations/'+op.id,{method:'PATCH',body:JSON.stringify({status:'awaiting_owner',by:'kira',note:'Research report saved with source references.',result:result.report,evidence,blocker:''})});
op=finished.operation;data.operations=[op,...(data.operations||[]).filter(x=>x.id!==op.id)];save();render();notify('Research complete. Kira has brought back '+evidence.length+' source links for your review.');
}catch(err){
if(op?.id){try{const blocked=await apiRequest('/api/operations/'+op.id,{method:'PATCH',body:JSON.stringify({status:'blocked',by:'kira',note:'Research could not be completed.',blocker:err.message})});data.operations=[blocked.operation,...(data.operations||[]).filter(x=>x.id!==op.id)];save()}catch{}}
render();notify('Research stopped: '+err.message);
}finally{if(op?.id)operationRuns.delete(op.id)}
}

async function developOpportunity(id){
if(!hasCloudSession()){notify('Sign in to the live workspace before developing a researched opportunity.');return}
if(operationRuns.has(id))return;
const research=(data.operations||[]).find(x=>x.id===id);
if(!research||research.type!=='opportunity_assessment'||research.status!=='awaiting_owner'||!research.result){notify('This research item is not awaiting a decision.');return}
operationRuns.add(id);
let preparation=null;
try{
const business=String(data.settings.business||'your business').trim();
const name=business+' researched opportunity';
const sourceLines=(research.evidence||[]).slice(0,6).map(x=>x.label+': '+x.url).join('\n');
const offer=('Evidence-backed research brief:\n'+research.result+'\n\nSource references:\n'+sourceLines).slice(0,1950);
preparation=(await apiRequest('/api/operations',{method:'POST',body:JSON.stringify({type:'campaign_preparation',title:'Develop selected opportunity for '+business,summary:'Turn the owner-selected research into an approval-ready campaign. Public claims must remain within the cited evidence.',priority:'high',source:{kind:'kira',label:'Selected research opportunity',url:research.evidence?.[0]?.url||''},evidence:research.evidence||[]})})).operation;
preparation=(await apiRequest('/api/operations/'+preparation.id,{method:'PATCH',body:JSON.stringify({status:'in_progress',by:'kira',note:'Owner selected this researched opportunity for campaign development.'})})).operation;
const campaign=makeCampaign({name,offer,audience:data.settings.audience||'The business’s intended customers',goal:'Engagement',angle:'community'});
const generated=await apiRequest('/api/generate',{method:'POST',body:JSON.stringify({name:campaign.name,offer:campaign.offer,audience:campaign.audience,goal:campaign.goal,marketingGoal:'Develop the strongest evidence-backed campaign opportunity',angle:campaign.angle,business:data.settings.business,businessDescription:data.settings.businessDescription||'',inventorySummary:aiInventoryContext(),brandVoice:data.settings.voice,platforms:(data.settings.platforms||'').split(',').map(x=>x.trim()).filter(Boolean),channelSetup:data.settings.channelSetup||{}})});
const g=generated.campaign||{};
if(!Array.isArray(g.posts)||g.posts.length!==3)throw Error('Kira did not return three complete campaign posts.');
campaign.strategy=g.strategy||'Developed from the selected, source-backed research. Verify all claims before approval.';
campaign.audienceInsight=g.audienceInsight||'';
campaign.channelPlan=Array.isArray(g.channelPlan)?g.channelPlan:[];
campaign.successMetrics=Array.isArray(g.successMetrics)?g.successMetrics:[];
campaign.posts=campaign.posts.map((old,i)=>({...old,...g.posts[i],id:old.id,status:'pending',scheduledDate:'',metrics:old.metrics||{}}));
campaign.createdBy='Kira';campaign.sourceOperationId=research.id;campaign.researchEvidence=research.evidence||[];
await saveCloudCampaign(campaign);
data.campaigns.push(campaign);save();
const ready=await apiRequest('/api/operations/'+preparation.id,{method:'PATCH',body:JSON.stringify({status:'awaiting_owner',by:'kira',note:'Campaign draft saved. Owner approval is still required before publication.',result:'Campaign draft “'+campaign.name+'” is ready in To review.'})});
preparation=ready.operation;data.operations=[preparation,...(data.operations||[]).filter(x=>x.id!==preparation.id)];
try{await apiRequest('/api/operations/'+research.id,{method:'PATCH',body:JSON.stringify({status:'in_progress',by:'owner',note:'Owner selected this opportunity for campaign development.'})});const closed=await apiRequest('/api/operations/'+research.id,{method:'PATCH',body:JSON.stringify({status:'completed',by:'kira',note:'Selected opportunity has been converted into a campaign draft.',result:'Campaign draft: '+campaign.name})});data.operations=[closed.operation,...(data.operations||[]).filter(x=>x.id!==research.id)];}catch(err){console.warn('Research operation close-out needs a refresh:',err.message)}
save();view='approvals';render();notify('Kira has turned the selected research into a campaign draft. It is waiting for your approval.');
}catch(err){
if(preparation?.id){try{const blocked=await apiRequest('/api/operations/'+preparation.id,{method:'PATCH',body:JSON.stringify({status:'blocked',by:'kira',note:'Campaign preparation could not be completed.',blocker:err.message})});data.operations=[blocked.operation,...(data.operations||[]).filter(x=>x.id!==blocked.operation.id)];save()}catch{}}
render();notify('Campaign preparation stopped: '+err.message);
}finally{operationRuns.delete(id)}
}
