function operationCard(o){
const states={queued:{label:'Queued',className:'queued',explain:'Recorded and waiting to start.'},in_progress:{label:'In progress',className:'active',explain:'The current run is marked in progress.'},awaiting_owner:{label:'Your decision needed',className:'pending',explain:'Kira has finished this step and is waiting for your decision.'},blocked:{label:'Blocked',className:'blocked',explain:'This work cannot continue until the blocker is resolved.'},completed:{label:'Completed',className:'done',explain:'This work is finished.'},cancelled:{label:'Cancelled',className:'cancelled',explain:'This work was stopped and will not continue.'}};
const state=states[o.status]||{label:String(o.status||'Unknown').replaceAll('_',' '),className:'queued',explain:'Status supplied by the workspace.'};
const type=String(o.type||'work').replaceAll('_',' ');
const updated=o.updatedAt&&Number.isFinite(Date.parse(o.updatedAt))?new Date(o.updatedAt).toLocaleString():'Time not recorded';
const history=Array.isArray(o.history)?o.history:[],latest=history.length?history[history.length-1]:null;
const historyHtml=history.length?'<details class="operation-history"><summary>Work history ('+history.length+')</summary><ol>'+history.slice(-5).map(h=>{const actor=h.by==='kira'?'Kira':h.by==='owner'?'You':'Workspace';const label=states[h.status]?.label||String(h.status||'Update').replaceAll('_',' ');const at=h.at&&Number.isFinite(Date.parse(h.at))?new Date(h.at).toLocaleString():'Time not recorded';return '<li><b>'+esc(label)+'</b><span> · '+esc(actor)+' · '+esc(at)+'</span>'+(h.note?'<p>'+esc(h.note)+'</p>':'')+'</li>'}).join('')+'</ol></details>':'';
return '<article class="campaign-card operation-card operation-'+esc(state.className)+'" data-operation-id="'+esc(o.id)+'"><div class="campaign-card-top"><span class="campaign-swatch">✳</span><span class="operation-state '+esc(state.className)+'">'+esc(state.label)+'</span></div><h3>'+esc(o.title)+'</h3><p>'+esc(o.summary)+'</p><div class="campaign-meta"><span>'+esc(type)+'</span><span>'+esc(o.priority||'normal')+' priority</span></div><p class="operation-state-copy">'+esc(state.explain)+'</p>'+(latest&&latest.note?'<p class="operation-note"><b>Latest update</b><br>'+esc(latest.note)+'</p>':'')+(o.type==='opportunity_assessment'&&o.status==='awaiting_owner'&&o.result?'<div class="card-actions"><button class="btn btn-primary" data-action="develop-opportunity" data-id="'+esc(o.id)+'">Build campaign from this</button></div>':'')+(o.type==='opportunity_assessment'&&o.status==='completed'&&o.campaignId?'<div class="card-actions"><button class="btn btn-primary" data-action="review" data-id="'+esc(o.campaignId)+'">Review campaign draft ↗</button></div>':'')+(o.result?'<div class="operation-result"><b>'+(o.status==='completed'?'Completed result':'Work result')+'</b><p>'+esc(o.result).replace(/\n/g,'<br>')+'</p></div>':'')+(Array.isArray(o.evidence)&&o.evidence.length?'<div class="operation-sources"><b>Evidence and sources</b>'+o.evidence.map(e=>'<a href="'+esc(e.url)+'" target="_blank" rel="noopener noreferrer">'+esc(e.label||e.url)+'</a>').join('')+'</div>':'')+(o.status==='blocked'?'<div class="operation-blocker"><b>What is stopping this</b><p>'+esc(o.blocker||'The workspace has marked this item as blocked but has not supplied a reason.')+'</p>'+(o.type==='opportunity_assessment'&&hasCloudSession()?'<p>Retry uses the current business profile and starts a new live research attempt on this same work record.</p><button class="btn btn-primary" data-action="retry-research" data-id="'+esc(o.id)+'">Retry research</button>':'')+'</div>':'')+historyHtml+'<p class="fine-print">Updated '+esc(updated)+'</p></article>';
}
function operations(){const items=Array.isArray(data.operations)?[...data.operations]:[];return header('KIRA’S WORK','Operations','See what Kira has finished, what needs your call and what is waiting on a dependency.','<button class="btn btn-white" data-action="operations-refresh">↻ Refresh</button><button class="btn btn-primary" data-action="operations-research">Research opportunities</button>')+(items.length?'<div class="campaign-grid operation-grid">'+items.map(operationCard).join('')+'</div>':empty('✳','No operations recorded yet','When Kira starts a piece of work, its recorded status and decision history will appear here.'))+'<p class="fine-print" style="text-align:left;margin-top:16px">'+(hasCloudSession()?'Showing the signed-in workspace queue.':'Showing this device’s local queue.')+'</p>'}

function approvals(){const queue=data.campaigns.filter(c=>c.status==='pending'||c.status==='rejected');const counts={All:queue.length,Pending:queue.filter(c=>c.status==='pending').length,'Sent back':queue.filter(c=>c.status==='rejected').length};let items=queue;if(approvalFilter==='Pending')items=items.filter(c=>c.status==='pending');if(approvalFilter==='Sent back')items=items.filter(c=>c.status==='rejected');const emptyCopy=approvalFilter==='Pending'?['No pending campaigns','There are no new campaigns waiting for a decision.']:approvalFilter==='Sent back'?['Nothing sent back','No campaigns are waiting for another look after changes.']:['Nothing in the queue','No campaigns need your attention right now.'];return header('YOUR CALL','Your call.','Review each campaign before deciding.')+'<div class="filter-row" role="group" aria-label="Filter campaigns needing a decision">'+['All','Pending','Sent back'].map(f=>'<button class="filter-btn '+(approvalFilter===f?'active':'')+'" data-filter="'+f+'" aria-pressed="'+(approvalFilter===f?'true':'false')+'">'+f+' <span class="filter-count">'+counts[f]+'</span></button>').join('')+'</div>'+(items.length?'<div class="campaign-grid">'+items.map(c=>campaignCard(c,true)).join('')+'</div>':empty('✓',emptyCopy[0],emptyCopy[1]))}
function studio(){const items=[...data.campaigns].reverse();return header('THE STUDIO','Campaigns','Your campaign line-up.','<button class="btn btn-primary" data-action="new-campaign">＋ New campaign</button>')+(items.length?'<div class="campaign-grid">'+items.map(campaignCard).join('')+'</div>':empty('✳','The studio is ready','Tell me what we’re promoting and I’ll build a first campaign draft.','<button class="btn btn-primary" data-action="new-campaign">Start the first one ↗</button>'))}
function schedule(){const items=data.campaigns.filter(c=>['scheduled','active','approved'].includes(c.status)).flatMap(c=>c.posts.filter(p=>p.scheduledDate).map(p=>({...p,campaignName:c.name,campaignId:c.id}))).sort((a,b)=>a.scheduledDate.localeCompare(b.scheduledDate));return header('THE PLAN','Schedule','What goes out, and when.')+(items.length?'<div class="schedule-list">'+items.map(p=>'<div class="schedule-item"><div class="schedule-time">'+esc(dateFmt(p.scheduledDate))+'</div><div class="schedule-bar"></div><div class="schedule-copy"><b>'+esc(p.title)+' · '+esc(p.campaignName)+'</b><small>'+esc(p.platform)+' · '+esc(p.copy.slice(0,100))+(p.copy.length>100?'…':'')+'</small></div>'+pill(p.status)+'</div>').join('')+'</div>':'')+(!items.length?empty('▦','Nothing scheduled just yet','Approve a campaign, then add dates to its posts. I’ll keep the plan tidy.','<button class="btn btn-primary" data-view="approvals">Review campaigns ↗</button>'):'')+'<p class="fine-print" style="text-align:left;margin-top:20px">This is a planning schedule. Automatic social publishing needs a connected platform integration.</p>'}
function results(){const items=[...data.campaigns].filter(c=>c.status==='completed').reverse();const playbook='<section class="panel settings-card"><p class="eyebrow">KIRA’S BUSINESS MEMORY</p><h2>What Kira has learned</h2><p class="subhead">Evidence-backed lessons from this business, used to shape future campaign decisions. Owner-entered reports remain separate and are not treated as verified platform data.</p>'+(hasCloudSession()?(learningMemory.length?'<div class="learning-playbook-list">'+learningMemory.map(entry=>'<article class="learning-playbook-entry"><div class="campaign-card-top"><b>'+esc(entry.campaignName||'Campaign lesson')+'</b><span class="report-note">'+esc(entry.confidence||'')+' confidence</span></div><p class="report-note">Facebook Graph API · '+esc(entry.reviewedAt?new Date(entry.reviewedAt).toLocaleDateString():'Date unavailable')+'</p>'+(entry.metrics?'<p class="report-note">'+(entry.metrics.impressions==null?'':'Impressions '+esc(entry.metrics.impressions)+' · ')+(entry.metrics.engagedUsers==null?'':'Engaged '+esc(entry.metrics.engagedUsers)+' · ')+(entry.metrics.clicks==null?'':'Clicks '+esc(entry.metrics.clicks))+'</p>':'')+(entry.whatWorked?.length?'<p><b>What worked</b></p><ul>'+entry.whatWorked.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+(entry.whatNeedsAttention?.length?'<p><b>Needs attention</b></p><ul>'+entry.whatNeedsAttention.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+(entry.nextAction?'<p><b>Next action:</b> '+esc(entry.nextAction)+'</p>':'')+'</article>').join('')+'</div>':'<p class="report-note">No verified platform lessons have been saved for this business yet. Kira adds them after she reviews eligible campaign results.</p>'):'<p class="report-note">Connect the live workspace to view Kira’s persistent business memory.</p>')+'</section>';return header('WHAT WORKED','Results & Archive','Results and lessons from finished campaigns.')+playbook+(items.length?'<div class="campaign-grid">'+items.map(c=>'<article class="campaign-card"><div class="campaign-card-top"><span class="campaign-swatch">↗</span>'+pill(c.status)+'</div><h3>'+esc(c.name)+'</h3><p>'+esc(c.offer)+'</p><div class="report-metrics"><div class="report-metric"><small>Reach</small><b>'+esc(c.actual?.reach||'Not added')+'</b></div><div class="report-metric"><small>Engagements</small><b>'+esc(c.actual?.engagements||'Not added')+'</b></div><div class="report-metric"><small>Clicks</small><b>'+esc(c.actual?.clicks||'Not added')+'</b></div></div><p><b>What we learned</b><br>'+esc(c.notes||'No lesson added yet.')+'</p><div class="card-actions"><button class="btn btn-primary" data-action="report" data-id="'+c.id+'">Open report</button><button class="btn btn-white" data-action="export" data-id="'+c.id+'">Export report</button></div></article>').join('')+'</div>':empty('↗','The learning library starts after campaign one','When a campaign finishes, we’ll record its goals, real results and lessons. Those notes become the recipe book for what comes next.'))}
function settings(){return header('MAKE IT FEEL LIKE YOUR BUSINESS','A few useful details','I’ll use these details to shape future campaign drafts. Fill in what you know; leave the rest blank for now.')+businessProfilesPanel()+'<section class="panel settings-card"><form id="settings-form"><label>Business or brand name<input name="business" value="'+esc(data.settings.business)+'" placeholder="Your business name"></label><label>Business location or service area<input name="businessLocation" value="'+esc(data.settings.businessLocation||'')+'" placeholder="City, region or service area"></label><label>Who are we trying to reach?<textarea name="audience" rows="2" placeholder="Regular customers, local families, collectors…">'+esc(data.settings.audience)+'</textarea></label><label>How should the brand sound?<textarea name="voice" rows="2">'+esc(data.settings.voice)+'</textarea></label><label>Platforms you use<input name="platforms" value="'+esc(data.settings.platforms)+'" placeholder="Facebook, Instagram…"></label><div class="monitoring-setting"><label class="check-label"><input type="checkbox" name="autoResearchEnabled" '+(data.settings.autoResearchEnabled?'checked':'')+'><span><b>Let Kira scan for opportunities every day</b><small>When enabled and connected, Kira can run the configured daily opportunity scan and save useful findings for your review. The workspace must be running at its scheduled time; search providers may contact external search engines.</small></span></label></div><div class="inventory-intake"><label>Inventory spreadsheet<input type="file" id="inventory-file" accept=".csv,.xlsx,.xls"></label><p id="inventory-status" class="fine-print">'+(data.settings.inventorySummary?esc(data.settings.inventorySummary.rowCount+" inventory rows loaded from "+data.settings.inventorySummary.fileName+"."):"Upload your stock list to ground campaign concepts in real products and prices.")+(data.settings.inventoryCloudStorageAvailable===false?" Full list remains on this device until the live workspace is updated.":"")+'</p></div><details class="advanced-settings"><summary>Advanced connections (optional)</summary><label>Live workspace address<input name="apiUrl" value="'+esc(data.settings.apiUrl||'')+'" placeholder="http://localhost:8787 or your hosted API address"></label><div class="api-check-row"><button class="btn btn-white" type="button" data-action="test-api">Test connection</button><span id="api-health-result" role="status">Not checked yet</span></div><label>Owner sign-in password<input name="apiPassword" type="password" autocomplete="current-password" placeholder="Only used to sign in"></label><p class="fine-print">Use this to connect a self-hosted local workspace or another configured API. For a local Docker installation on this device, use http://localhost:8787. Without a connection, you can still create and save local drafts.</p></details><div class="card-actions"><button class="btn btn-primary" type="submit">Save my details ✓</button><button class="btn btn-white" type="button" data-action="export-data">Export my data</button><button class="btn btn-danger" type="button" data-action="reset-data">Clear device data</button>'+(hasCloudSession()?'<button class="btn btn-white" type="button" data-action="delete-cloud-data">Delete cloud campaigns</button><button class="btn btn-white" type="button" data-action="delete-cloud-operations">Delete cloud operations</button><button class="btn btn-white" type="button" data-action="sign-out">Sign out on this device</button>':'')+'</div></form></section><section class="panel settings-card privacy-panel"><p class="eyebrow">YOUR INFORMATION</p><h2>Privacy & data</h2><p><b>On this device:</b> your business profile, campaign drafts, inventory summary, operation history and conversation history are saved in this browser. Clearing device data removes that local workspace.</p><p><b>When connected:</b> campaign and operation records, including research reports and source links, are stored by the workspace you connect. AI requests are sent to the connected workspace model provider. With the self-hosted setup, Kira chat and campaign generation use the local Ollama model; research uses your private SearXNG service, which queries external public search engines. With a hosted setup, data handling depends on that provider terms and configuration. If daily opportunity scans are enabled, the workspace runs its scheduled research task only while the service is online. Kira saves the resulting report and source links for owner review.</p><p><b>Access:</b> your owner password is used only to sign in. The short-lived access token is held in this browser tab and expires after 12 hours. Signing out removes it from this tab.</p><p><b>Control:</b> export includes the device data and, when connected, the cloud campaign records. Delete cloud campaigns removes campaign records from the cloud and this device. Delete cloud operations separately removes operation records, research reports and their saved source links from the cloud and this device. Neither action disconnects third-party accounts or deletes provider-side request records.</p><p class="fine-print">Only provide information needed for the marketing task. Avoid uploading customer names, contact details, payment information or sensitive personal information. Do not use customer lists as campaign context.</p></section>'}
