function recommendedChannels(){const mixes={local:['facebook','google','website','instagram'],sales:['facebook','instagram','website','google'],online:['instagram','tiktok','youtube','website'],b2b:['linkedin','website','google'],marketplace:['trademe','facebook','website']};return mixes[data.settings.marketingGoal||'local']||mixes.local}
async function assessChannelsWithKira(){
if(!hasCloudSession()){notify("Connect Kira’s live workspace in Settings to run a personalised AI channel assessment.");view="settings";render();return;}
const button=$('[data-action="assess-channels"]');if(button){button.disabled=true;button.textContent="Kira is assessing…";}
try{
const channels=CHANNELS.map(c=>({id:c.id,name:c.name,group:c.group,description:c.why,accessRequirements:c.access}));
const result=await apiRequest("/api/strategy",{method:"POST",body:JSON.stringify({business:data.settings.business,description:data.settings.businessDescription||"",audience:data.settings.audience||"",goal:data.settings.marketingGoal||"local",brandVoice:data.settings.voice||"",channels})});
data.settings.channelStrategy=result;data.settings.channelSetup=data.settings.channelSetup||{};
const selected=new Set(result.recommendedChannels||[]);
CHANNELS.forEach(c=>{const d=channelData(c.id);d.selected=selected.has(c.id);data.settings.channelSetup[c.id]=d;});
save();render();notify("Kira’s channel assessment is ready. Review the recommendations before continuing. ✓");
}catch(err){notify("Kira could not complete the live assessment: "+err.message);}
finally{const current=$('[data-action="assess-channels"]');if(current){current.disabled=false;current.textContent="Ask Kira to assess channels ↻";}}
}
