 const metrics=c.successMetrics?.length?'<div class="review-insight"><b>How we’ll judge success</b><ul>'+c.successMetrics.map(m=>'<li>'+esc(m)+'</li>').join('')+'</ul></div>':'';
 card.classList.add('campaign-review');
 card.innerHTML='<div class="review-topline"><span class="eyebrow">CAMPAIGN REVIEW</span>'+pill(c.status)+'</div><h2>'+esc(c.name)+'</h2><p class="review-offer">'+esc(c.offer)+'</p><p class="review-status-line">'+esc(statusText)+' · '+posts.length+' '+(posts.length===1?'post':'posts')+'</p><div class="review-summary"><div><small>Audience</small><b>'+esc(c.audience||'Not specified')+'</b></div><div><small>Goal</small><b>'+esc(c.goal||'Not specified')+'</b></div><div><small>Approach</small><b>'+esc(angleLabel(c.angle))+'</b></div></div><section class="review-section"><h3>Kira’s thinking</h3><p class="review-explanation">Here’s the approach behind the campaign. Check that the message, audience and offer are right before approving.</p>'+strategy+audience+channels+metrics+researchEvidencePanel(c)+'</section><section class="review-section"><div class="review-section-heading"><div><h3>The content</h3><p>Edit the wording or set dates before you approve.</p></div><span class="review-count">'+posts.length+' '+(posts.length===1?'post':'posts')+'</span></div>'+posts.map((p,i)=>'<article class="review-post"><div class="review-post-heading"><span class="review-post-number">'+String(i+1).padStart(2,'0')+'</span><div><b>'+esc(p.title||'Untitled post')+'</b><small>'+esc(p.platform||'Platform not set')+' · '+esc(p.objective||'Content post')+'</small></div></div>'+(p.visualBrief?'<p class="review-visual"><b>Visual direction</b> '+esc(p.visualBrief)+'</p>':'')+'<label class="review-copy-label">Post copy<textarea data-copy="'+esc(p.id)+'" rows="5">'+esc(p.copy||'')+'</textarea></label>'+(p.cta?'<p class="review-cta"><b>Call to action</b> '+esc(p.cta)+'</p>':'')+'<div class="review-post-controls"><label>Planned date<input type="date" data-date="'+esc(p.id)+'" value="'+esc(p.scheduledDate||'')+'"></label><label>Post status<select data-poststatus="'+esc(p.id)+'">'+['pending','approved','scheduled'].map(s=>'<option '+(p.status===s?'selected':'')+' value="'+s+'">'+(s==='pending'?'Needs review':s==='approved'?'Approved':'Scheduled')+'</option>').join('')+'</select></label></div></article>').join('')+'</section><section class="review-section review-targets"><h3>Optional targets</h3><div class="review-target-grid"><label>Expected reach<input data-expect="reach" value="'+esc(c.expected?.reach??'')+'" placeholder="e.g. 1,000 people"></label><label>Expected engagement rate<input data-expect="engagementRate" value="'+esc(c.expected?.engagementRate??'')+'" placeholder="e.g. 4%"></label></div><p>Targets are planning estimates, not guaranteed results.</p></section><div class="review-actions"><button class="btn btn-primary" data-action="save-review" data-id="'+esc(c.id)+'">Save changes</button>'+(c.status==='pending'||c.status==='rejected'?'<button class="btn btn-white" data-action="reject" data-id="'+esc(c.id)+'">Send back for changes</button><button class="btn btn-soft" data-action="approve-campaign" data-id="'+esc(c.id)+'">Approve campaign</button>':'')+'<button class="btn btn-white" data-action="close-review">Back to campaigns</button></div><p class="review-footer-note">Nothing is published when you save or approve. Publishing remains a separate action.</p>';
 card.querySelectorAll('[data-copy]').forEach(el=>el.addEventListener('input',()=>{const p=posts.find(x=>String(x.id)===el.dataset.copy);if(p){p.copy=el.value;save()}}));
