function scheduleCampaign(c){const today=new Date();today.setHours(12,0,0,0);c.posts.forEach((p,i)=>{if(!p.scheduledDate){const d=new Date(today);d.setDate(d.getDate()+1+i*2);p.scheduledDate=d.toISOString().slice(0,10)}p.status='scheduled'});c.status='scheduled';save();updateCloudCampaign(c).catch(err=>notify('Saved here, but cloud sync failed: '+err.message));view='schedule';render();notify('Dates added. Have a look at the schedule.')}
function finishCampaign(c){if(!confirm('Mark “'+c.name+'” as finished and prepare its results report?'))return;c.status='completed';c.completedAt=new Date().toISOString();save();reportCampaign(c)}
function reportCampaign(c){const root=$('#view-root');view='results';render();const fbPosts=(c.posts||[]).filter(p=>p.status==='published'&&p.platform==='Facebook'&&p.platformPostId);const fb=c.facebookResults||null;const fbPanel=hasCloudSession()&&fbPosts.length?'<section class="panel settings-card"><h3>Facebook results</h3><p class="subhead">Import verified figures from '+fbPosts.length+' published Facebook '+(fbPosts.length===1?'post':'posts')+'. Impressions are not the same as unique reach.</p>'+(fb?'<div class="report-metrics"><div class="report-metric"><small>Impressions</small><b>'+esc(fb.impressions??'Not returned')+'</b></div><div class="report-metric"><small>Engaged users</small><b>'+esc(fb.engagedUsers??'Not returned')+'</b></div><div class="report-metric"><small>Clicks</small><b>'+esc(fb.clicks??'Not returned')+'</b></div></div><p class="report-note">Last retrieved '+esc(new Date(fb.retrievedAt).toLocaleString())+' · '+esc(fb.postsRetrieved)+' posts returned data</p>':'<p class="report-note">No platform figures have been imported yet.</p>')+'<button class="btn btn-white" type="button" data-action="refresh-facebook-results" data-id="'+esc(c.id)+'">Refresh Facebook results</button></section>':'';const learning=c.learning;const learningPanel=learning?.analysis?'<section class="panel settings-card"><h3>Kira’s campaign review</h3><p class="report-note">Evidence: '+esc(learning.source||'Recorded campaign results')+' · Confidence: '+esc(learning.analysis.confidence||'not rated')+(learning.partial?' · Partial results':'')+'</p><p>'+esc(learning.analysis.summary||'')+'</p>'+(learning.analysis.whatWorked?.length?'<p><b>What worked</b></p><ul>'+learning.analysis.whatWorked.map(item=>'<li>'+esc(item)+'</li>').join('')+'</ul>':'')+(learning.analysis.whatNeedsAttention?.length?'<p><b>What needs attention</b></p><ul>'+learning.analysis.whatNeedsAttention.map(item=>'<li>'+esc(item)+'</li>').join('')+'</ul>':'')+'<p><b>Next action:</b> '+esc(learning.analysis.nextAction||'')+'</p></section>':'';root.innerHTML=header('CAMPAIGN WRAP-UP','Let’s get the real story.','Pop in the numbers you have. Leave anything unknown blank. We’ll keep actual results separate from expectations.')+fbPanel+learningPanel+'<section class="panel settings-card"><h2>'+esc(c.name)+'</h2><p class="subhead">'+esc(c.offer)+'</p><form id="report-form"><div class="report-metrics"><label class="report-metric"><small>Actual reach</small><input name="reach" type="number" min="0" value="'+esc(c.actual.reach)+'" placeholder="0"></label><label class="report-metric"><small>Engagements</small><input name="engagements" type="number" min="0" value="'+esc(c.actual.engagements)+'" placeholder="0"></label><label class="report-metric"><small>Link clicks</small><input name="clicks" type="number" min="0" value="'+esc(c.actual.clicks)+'" placeholder="0"></label></div><div class="form-grid"><label>Conversions / enquiries<input name="conversions" type="number" min="0" value="'+esc(c.actual.conversions)+'" placeholder="If tracked"></label><label>Actual spend<input name="spend" value="'+esc(c.actual.spend||'')+'" placeholder="$0 or unknown"></label></div><label>What worked or surprised us?<textarea name="notes" rows="3" placeholder="Best post, customer reactions, useful surprises…">'+esc(c.notes)+'</textarea></label><label>What should we try next time?<textarea name="lesson" rows="3" placeholder="One or two useful lessons">'+esc(c.lesson||'')+'</textarea></label><div class="report-note">Only enter numbers you can verify. This app does not currently import engagement data directly from social platforms.</div><div class="card-actions"><button class="btn btn-primary" type="submit">Save campaign report ✓</button><button class="btn btn-white" type="button" data-action="export" data-id="'+c.id+'">Export current report</button></div></form></section>';$('#report-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);for(const k of ['reach','engagements','clicks','conversions','spend'])c.actual[k]=f.get(k)||'';c.notes=f.get('notes')||'';c.lesson=f.get('lesson')||'';c.reportUpdatedAt=new Date().toISOString();save();updateCloudCampaign(c).catch(err=>notify('Report saved here, but cloud sync failed: '+err.message));render();notify('Saved. Those lessons are in the archive. ✨')})}
async function refreshFacebookResults(c){const button=document.querySelector('[data-action="refresh-facebook-results"][data-id="'+CSS.escape(String(c.id))+'"]');if(button){button.disabled=true;button.textContent='Retrieving results…'}try{const posts=(c.posts||[]).filter(p=>p.status==='published'&&p.platform==='Facebook'&&p.platformPostId);if(!posts.length)throw Error('There are no confirmed published Facebook posts in this campaign.');const settled=await Promise.allSettled(posts.map(p=>apiRequest('/api/analytics',{method:'POST',body:JSON.stringify({campaignId:c.id,postId:p.id})})));const totals={impressions:0,engagedUsers:0,clicks:0};const found={impressions:false,engagedUsers:false,clicks:false};let postsRetrieved=0;const errors=[];settled.forEach((item,index)=>{if(item.status!=='fulfilled'){errors.push(posts[index].title+': '+item.reason.message);return}const metrics=Array.isArray(item.value.metrics)?item.value.metrics:[];if(metrics.length)postsRetrieved++;for(const metric of metrics){const raw=metric?.total_value?.value??metric?.values?.[0]?.value;const value=typeof raw==='number'?raw:Number(raw);if(!Number.isFinite(value))continue;const key=metric.name==='post_impressions'?'impressions':metric.name==='post_engaged_users'?'engagedUsers':metric.name==='post_clicks'?'clicks':null;if(key){totals[key]+=value;found[key]=true}}});if(!postsRetrieved)throw Error(errors[0]||'Facebook returned no usable metrics for these posts.');c.facebookResults={impressions:found.impressions?totals.impressions:null,engagedUsers:found.engagedUsers?totals.engagedUsers:null,clicks:found.clicks?totals.clicks:null,postsRetrieved,retrievedAt:new Date().toISOString(),source:'Facebook Graph API',partial:errors.length>0};save();await updateCloudCampaign(c);reportCampaign(c);notify(errors.length?'Facebook results partly retrieved. '+errors.length+' post(s) could not be read.':'Facebook results updated. ✓')}catch(err){if(button){button.disabled=false;button.textContent='Refresh Facebook results'}notify('Could not retrieve Facebook results: '+err.message)}}
function reportData(c){return {campaign:c.name,offer:c.offer,status:c.status,createdAt:c.createdAt,completedAt:c.completedAt||null,goal:c.goal,audience:c.audience,angle:angleLabel(c.angle),posts:c.posts.map(p=>({title:p.title,platform:p.platform,scheduledDate:p.scheduledDate,status:p.status,copy:p.copy,metrics:p.metrics})),expectations:c.expected,actualResults:c.actual,facebookResults:c.facebookResults||null,lessons:c.notes,nextTime:c.lesson,reportUpdatedAt:c.reportUpdatedAt||null,dataSource:c.facebookResults?'Facebook Graph API plus manually entered results':'Manually entered results'}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){view=nav.dataset.view;document.querySelector('.sidebar')?.classList.remove('menu-open');$('#menu-toggle')?.setAttribute('aria-expanded','false');render();if(view==='operations')refreshOperations();if(view==='results')refreshLearningMemory();return}const f=e.target.closest('[data-filter]');if(f){approvalFilter=f.dataset.filter;render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='publish-post'){const c=data.campaigns.find(x=>x.id===id),p=c?.posts?.find(x=>x.id===b.dataset.postId);if(c&&p)publishPost(c,p);return}if(a==='refresh-facebook-results'){const c=data.campaigns.find(x=>x.id===id);if(c)refreshFacebookResults(c);return}if(a==='test-api'){testLiveServices();return}if(a==='add-business-profile'){addBusinessProfile();return}if(a==='assess-channels'){assessChannelsWithKira();return}if(a==='connection-step'){data.settings.onboardingStep=Number(b.dataset.step||1);save();render();return}if(a==='connection-status'){data.settings.channelSetup=data.settings.channelSetup||{};const d=channelData(id);d.status=b.dataset.status||'setup_started';data.settings.channelSetup[id]=d;save();render();notify('Checklist updated. This does not verify a live connection.');return}if(a==='close-review'){render();return}if(a==='save-review'){const c=data.campaigns.find(x=>x.id===id);if(c){const card=document.querySelector('[data-campaign-id="'+CSS.escape(String(id))+'"]');if(card){card.querySelectorAll('[data-copy]').forEach(el=>{const p=c.posts.find(x=>String(x.id)===el.dataset.copy);if(p)p.copy=el.value});card.querySelectorAll('[data-date]').forEach(el=>{const p=c.posts.find(x=>String(x.id)===el.dataset.date);if(p)p.scheduledDate=el.value});card.querySelectorAll('[data-poststatus]').forEach(el=>{const p=c.posts.find(x=>String(x.id)===el.dataset.poststatus);if(p)p.status=el.value});card.querySelectorAll('[data-expect]').forEach(el=>{c.expected=c.expected||{};c.expected[el.dataset.expect]=el.value})}if(c.posts.some(p=>p.status==='scheduled'&&!p.scheduledDate)){notify('Add a planned date to every post marked Scheduled.');return}save();updateCloudCampaign(c).catch(err=>notify('Saved on this device, but cloud sync failed: '+err.message));render();notify('Campaign changes saved. ✓')}return}act(a,id)});
$('#campaign-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const submit=form.querySelector('[type="submit"]');if(submit){submit.disabled=true;submit.textContent='Building campaign…'}const f=Object.fromEntries(new FormData(form));const c=makeCampaign(f);let aiBuilt=false;if(hasCloudSession()){try{const generated=await apiRequest('/api/generate',{method:'POST',body:JSON.stringify({name:c.name,offer:c.offer,audience:c.audience,goal:c.goal,marketingGoal:data.settings.marketingGoal||c.goal,angle:c.angle,business:data.settings.business,businessDescription:data.settings.businessDescription||'',inventorySummary:aiInventoryContext(),brandVoice:data.settings.voice,platforms:(data.settings.platforms||'').split(',').map(x=>x.trim()).filter(Boolean),channelSetup:data.settings.channelSetup||{}})});const g=generated.campaign||{};if(Array.isArray(g.posts)&&g.posts.length===3){c.strategy=g.strategy||'';c.audienceInsight=g.audienceInsight||'';c.channelPlan=Array.isArray(g.channelPlan)?g.channelPlan:[];c.successMetrics=Array.isArray(g.successMetrics)?g.successMetrics:[];c.posts=c.posts.map((old,i)=>({...old,...g.posts[i],id:old.id,status:'pending',scheduledDate:'',metrics:old.metrics||{}}));aiBuilt=true}}catch(err){notify('AI unavailable, using a local draft: '+err.message)}}data.campaigns.push(c);save();if(hasCloudSession()){try{await saveCloudCampaign(c)}catch(err){notify('Draft saved here, but cloud save failed: '+err.message)}}$('#campaign-dialog').close();form.reset();view='approvals';render();if(submit){submit.disabled=false;submit.textContent='Build my campaign ↗'}notify(aiBuilt?'AI campaign ready for your OK. Nothing has been published. ✓':'Campaign draft ready for your OK. Nothing has been published. ✓')});
$('#close-dialog').addEventListener('click',()=>$('#campaign-dialog').close());$('#cancel-dialog').addEventListener('click',()=>$('#campaign-dialog').close());
document.addEventListener('change',async e=>{if(e.target.id==='business-profile-select'){const id=e.target.value;try{await activateBusinessProfile(id)}catch(err){notify('Business switch failed: '+err.message);render()}return}const inventory=e.target.closest('#inventory-file');if(inventory&&inventory.files?.[0]){const file=inventory.files[0],status=$('#inventory-status');try{if(!window.XLSX)throw Error('Spreadsheet reader is still loading. Try again in a moment.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'});const sheet=workbook.Sheets[workbook.SheetNames[0]];const rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false});const summary=buildInventorySummary(rows,file.name);const previous=data.settings.inventorySummary;data.settings.inventorySummary=summary;if(!save()){data.settings.inventorySummary=previous;throw Error('The inventory was not saved. The file may be too large for this browser’s available storage. Your previous inventory has been kept.')}if(hasCloudSession())saveCloudProfile().then(ok=>{if(ok===false)notify('Inventory is saved on this device. The connected server needs its inventory update before it can store the full list.')}).catch(err=>console.warn('Could not sync inventory profile:',err.message));if(status)status.textContent='Loaded '+summary.rowCount+' rows and '+summary.products.length+' products from '+summary.fileName+'.';notify('Inventory loaded and saved. ✓')}catch(err){if(status)status.textContent=err.message;notify(err.message)}return}const cb=e.target.closest('[data-channel-select]');if(cb){data.settings.channelSetup=data.settings.channelSetup||{};const d=channelData(cb.dataset.channelSelect);d.selected=cb.checked;data.settings.channelSetup[cb.dataset.channelSelect]=d;save();render();return}const note=e.target.closest('[data-channel-note]');if(note){data.settings.channelSetup=data.settings.channelSetup||{};const d=channelData(note.dataset.channelNote);d.note=note.value;data.settings.channelSetup[note.dataset.channelNote]=d;data.settings.website=note.value;save();notify('Website details saved.')}});
document.addEventListener('submit',async e=>{if(e.target.id==='connection-business-form'){e.preventDefault();const f=new FormData(e.target);data.settings.business=f.get('business')||'';data.settings.businessDescription=f.get('description')||'';data.settings.audience=f.get('audience')||'';data.settings.marketingGoal=f.get('goal')||'local';data.settings.website=f.get('website')||'';data.settings.channelSetup=data.settings.channelSetup||{};const recommended=recommendedChannels();CHANNELS.forEach(channel=>{const d=channelData(channel.id);d.selected=recommended.includes(channel.id);if(channel.id==='website'&&data.settings.website)d.note=data.settings.website;data.settings.channelSetup[channel.id]=d});data.settings.onboardingStep=2;save();render();return}if(e.target.id!=='settings-form')return;e.preventDefault();const f=new FormData(e.target);const password=String(f.get('apiPassword')||'');data.settings={...data.settings,business:f.get('business')||'',businessLocation:f.get('businessLocation')||'',audience:f.get('audience')||'',voice:f.get('voice')||'',platforms:f.get('platforms')||'',apiUrl:f.get('apiUrl')||'',autoResearchEnabled:f.get('autoResearchEnabled')==='on'};save();if(password){try{await connectCloud(password);render();notify('Connected securely. Campaigns are synced. ✓')}catch(err){render();notify('Saved, but connection failed: '+err.message)}return}if(hasCloudSession()){try{await saveCloudProfile();await syncCloudBusinesses();await syncCloud();render();notify('Workspace synced. ✓')}catch(err){render();notify('Saved locally. Cloud sync failed: '+err.message)}return}render();notify('Saved on this device. Add your live workspace details to connect. ✓')});
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if($('#campaign-dialog').open){$('#campaign-dialog').close();return}const side=document.querySelector('.sidebar');if(side?.classList.contains('menu-open')){side.classList.remove('menu-open');$('#menu-toggle')?.setAttribute('aria-expanded','false')}});
render();
// Scheduled Kira work is created by the backend while the app may be closed.
// Refresh the signed-in business workspace on launch so new drafts and operations appear without a manual reconnect.
if(hasCloudSession()){
 Promise.resolve().then(()=>syncCloud()).then(()=>refreshOperations()).then(()=>render()).catch(err=>{
  console.warn('Could not refresh the live workspace on launch:',err.message);
  notify('Live workspace refresh needs attention: '+err.message);
 });
}
$('#sound-toggle')?.addEventListener('click',()=>{soundEnabled=!soundEnabled;if(soundEnabled){if(!startAmbient()){soundEnabled=false;return}}else stopAmbient();const b=$('#sound-toggle');if(b){b.textContent=soundEnabled?'♫ Sounds on':'♫ Sounds off';b.setAttribute('aria-pressed',String(soundEnabled))}soundCue('menu')});
